package com.example.bodega.reporte.controller;
import com.example.bodega.reporte.dto.*; import com.example.bodega.reporte.service.ReporteService; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.List;
@RestController @RequestMapping("/api/reportes") @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')")
public class ReporteController {private final ReporteService service;@GetMapping("/ventas") public ReporteVentasResponse ventas(@RequestParam LocalDate desde,@RequestParam LocalDate hasta){return service.ventas(desde,hasta);}@GetMapping("/productos-mas-vendidos") public List<ProductoVendidoResponse> masVendidos(@RequestParam LocalDate desde,@RequestParam LocalDate hasta){return service.masVendidos(desde,hasta);}@GetMapping("/valor-inventario") public ValorInventarioResponse valor(){return service.valorInventario();}}
